// ============================================
// 服务器地址配置（统一管理，方便修改）
// ============================================
// 主API服务器 - 用于搜索、详情、目录、正文、评论
const API_BASE = "https://fqapi.lxqteam.dpdns.org:8080";
const COMMENT_BASE = "https://fqapi.lxqteam.dpdns.org:8080";
// ============================================

function getServerHost() {
    let { source } = this;
    try {
        const config = JSON.parse(source.getVariable());
        if (Array.isArray(config) && config.length > 0) {
            return config[0].host || getApi();
        }
        else if (config && typeof config === "object") {
            return config.server || getApi();
        }
        return getApi();
    } catch(e) {
        return getApi();
    }
}
const host = [API_BASE];

function getApi() {
    try {
        var sv = source.getVariable() || "";
        if (sv && String(sv).indexOf('server') >= 0) {
            var obj = JSON.parse(sv);
            if (obj.server && /^https?:\/\//i.test(obj.server)) return obj.server.replace(/\/+$/, '');
        }
    } catch(e) {}
    return API_BASE.replace(/\/+$/, '');
}

function getArguments(open_argument, key) {
    try {
        open_argument = JSON.parse(open_argument);
    } catch (e) {
        open_argument = {
            "search": "-1",
            "tone_id": "-1",
            "sz": "0",
            "server": API_BASE,
            "tone": "",
            "st": 0,
            "type": "小说模式",
            "module": "3",
            "faxian": "小说",
            "小说路径": "content",
            "漫画路径": "content",
            "短篇路径": "content",
            "漫剧路径": "content",
            "cp": 1,
            "bk": 1,
            "dp": 1
        };
    }
    if (key) {return open_argument[key];} else {return open_argument}
}

function getCtxSource() { return this.source || source; }
function getCtxJava() { return this.java || java; }
function getCtxCache() { return this.cache || cache; }
function isDpEnabled() {
    try {
        let sv = JSON.parse(getCtxSource.call(this).getVariable() || "{}");
        return sv.dp != 0;
    } catch(e) {}
    return false;
}

var FQ_LAST_CMT_CLICK = null;
var _dpCfg = null;

// ===== 段评：统计 + 正文注入气泡 + 点击打开段评页 =====
// 项目接口: GET {server}/api/para_comment/stats?chapter_id={cid}&book_id={bid}
// 返回 data.paras = { "0": 683, "1": 40, ... } 段落索引 -> 评论数
function fqParaStatsUrl(bid, cid) {
    var server = getApi();
    return server + '/api/para_comment/stats?chapter_id=' + encodeURIComponent(String(cid || '')) + '&book_id=' + encodeURIComponent(String(bid || ''));
}

function getCommentsWithData(content, bid, cid, statsStr) {
    let { java, cache, source } = this;
    try {
        {
            try {
                var _li = source.getLoginInfoMap();
                _dpCfg = { color: '', tpl: '', size: '' };
                if (_li) {
                    var _c = String(_li['段评图标颜色(如#FF6347)'] || '').trim();
                    if (_c.startsWith('#') && _c.length >= 4) _dpCfg.color = _c;
                    _dpCfg.tpl = String(_li['段评气泡样式(留空用默认)'] || '').trim();
                    _dpCfg.size = String(_li['段评气泡大小'] || '').trim();
                }
            } catch(e) { _dpCfg = { color: '', tpl: '', size: '' }; }
        }
        let root = JSON.parse(statsStr || '{}');
        let raw = (root && root.data && root.data.paras) ? root.data.paras : {};
        let hasPTags = content.indexOf('</p>') >= 0;
        if (hasPTags) {
            let pRegex = /<p(?:\s[^>]*)?>[\s\S]*?<\/p>/g;
            let match;
            let textIdx = 0, imgIdx = 0;
            let paraInfo = {};
            while ((match = pRegex.exec(content)) !== null) {
                let inner = match[0].replace(/^<p[^>]*>/, '').replace(/<\/p>$/, '');
                let hasImg = /<img\b[^>]*>/i.test(inner);
                let textOnly = inner.replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').trim();
                if (!textOnly && !hasImg) continue;
                let closingPos = match.index + match[0].lastIndexOf('</p>');
                if (hasImg && !textOnly) {
                    paraInfo[20000 + imgIdx] = { closingP: closingPos, text: '[图片]' };
                    imgIdx++;
                } else {
                    paraInfo[textIdx] = { closingP: closingPos, text: textOnly || '[图片]' };
                    textIdx++;
                }
            }
            let insertions = [];
            Object.keys(raw).forEach((x) => {
                let count = Number(raw[x] || 0);
                let paraIndex = parseInt(x);
                if (!count || isNaN(paraIndex)) return;
                let info = paraInfo[paraIndex];
                if (!info) return;
                cache.putMemory('fq-' + bid + '-' + cid + '-' + x + '-text', info.text);
                let color = '#FF6347';
                let svgImg = '<img src="' + this.createSvg(count, color, bid, cid, x) + '">';
                insertions.push({pos: info.closingP, svg: svgImg});
            });
            insertions.sort((a, b) => b.pos - a.pos);
            for (let i = 0; i < insertions.length; i++) {
                content = content.substring(0, insertions[i].pos) + insertions[i].svg + content.substring(insertions[i].pos);
            }
        } else {
            let lines = content.split("\n");
            let imgLines = [];
            for (let i = 0; i < lines.length; i++) {
                if (lines[i].indexOf('<img') >= 0) imgLines.push(i);
            }
            Object.keys(raw).forEach((x) => {
                let count = Number(raw[x] || 0);
                let paraIndex = parseInt(x);
                if (!count || isNaN(paraIndex)) return;
                let actualLine = paraIndex;
                for (let i = 0; i < imgLines.length; i++) {
                    if (imgLines[i] <= actualLine) actualLine++;
                    else break;
                }
                if (actualLine < lines.length) {
                    let lineText = lines[actualLine].replace(/<[^>]+>/g, '').trim();
                    cache.putMemory('fq-' + bid + '-' + cid + '-' + x + '-text', lineText || '段评内容');
                    let color = '#4169e1';
                    lines[actualLine] += '<img src="' + this.createSvg(count, color, bid, cid, x) + '">';
                }
            });
            content = lines.join("\n");
        }
        return content;
    } catch (e) {
        try { java.log('段评数据获取失败：' + e); } catch (ignore) {}
        return content;
    }
}

function createSvg(number, color, bid, cid, para) {
    let { java, source } = this;
    var displayText = number > 999 ? '999' : String(number || 0);
    if (_dpCfg) {
        if (_dpCfg.color) color = _dpCfg.color;
        var tpl = _dpCfg.tpl || '';
        var sizeVal = _dpCfg.size || '';
    } else {
        try {
            var loginInfo = source.getLoginInfoMap();
            if (loginInfo) {
                var c = String(loginInfo['段评图标颜色'] || '').trim();
                if (c.startsWith('#') && c.length >= 4) color = c;
                var tpl = String(loginInfo['段评气泡样式'] || '').trim();
                var sizeVal = String(loginInfo['段评气泡大小'] || '').trim();
            }
        } catch(e) {}
    }
    var bubbleSize = (sizeVal === '小号') ? 'text' : 'TEXT';
    var svg;
    if (tpl && tpl.indexOf('<svg') >= 0) {
        svg = tpl.replace(/\$\{qpwzcolor\}/g, color)
                 .replace(/\$\{qpyscolor\}/g, color)
                 .replace(/\$\{displayText\}/g, displayText);
    } else {
        svg = '<svg width="160" height="120" xmlns="http://www.w3.org/2000/svg"><path d="M 55 10 L 120 10 Q 150 10 150 40 L 150 80 Q 150 110 120 110 L 55 110 Q 25 110 25 80 L 25 75 L 3 60 L 25 45 L 25 40 Q 25 10 55 10 Z" fill="none" stroke="' + color + '" stroke-width="5" stroke-linejoin="round"/><text x="87" y="77" font-family="Arial, sans-serif" text-anchor="middle" dominant-baseline="middle" font-size="50" font-weight="bold" fill="' + color + '">' + displayText + '</text></svg>';
    }
    var encodedSvg = java.base64Encode(svg);
    function esc(s) {
        if (s == null) return "";
        return String(s).replace(/\\/g, "\\\\").replace(/'/g, "\\'").replace(/\r/g, "").replace(/\n/g, "\\n");
    }
    var options = {
        style: bubbleSize,
        click: "showCmt('" + esc(bid) + "','" + esc(cid) + "','" + esc(para) + "')"
    };
    return 'data:image/svg+xml;base64,' + encodedSvg + ',' + JSON.stringify(options);
}

function showCmt(bid, cid, para) {
    let { java, cache } = this;
    var clickKey = String(bid) + '-' + String(cid) + '-' + String(para);
    var now = Date.now();
    if (FQ_LAST_CMT_CLICK && now - FQ_LAST_CMT_CLICK.time < 2500) return;
    FQ_LAST_CMT_CLICK = { key: clickKey, time: now };
    var paraText = '';
    try { paraText = cache.getFromMemory('fq-' + bid + '-' + cid + '-' + para + '-text') || ''; } catch(e) {}
    if (!paraText) paraText = '段评内容';
    var url = COMMENT_BASE + '/paragraph-comment.html?book_id=' + encodeURIComponent(String(bid || '')) + '&item_id=' + encodeURIComponent(String(cid || '')) + '&para_index=' + encodeURIComponent(String(para || '0')) + '&para_text=' + encodeURIComponent(String(paraText || ''));
    try {
        var html = java.ajax(COMMENT_BASE + '/paragraph-comment.html');
        java.showBrowser(url, html);
    } catch (e) {
        try { java.log('段评窗口打开失败：' + e); } catch (ignore) {}
        java.startBrowser(url, paraText || '段评');
    }
}

function getComments(content, bookId, itemId, chapterTitle) {
    if (!isDpEnabled.call(this)) {
        return content;
    }
    let javaHelper = getCtxJava.call(this);
    if (!content || !bookId || !itemId) return content;
    try {
        var statsStr = javaHelper.ajax(fqParaStatsUrl(bookId, itemId));
        if (statsStr) {
            content = getCommentsWithData.call(this, content, bookId, itemId, statsStr);
        }
    } catch(e) {}
    return content;
}

// ===== 书评功能 =====
function showBookCom() {
    const { java, source } = this;
    var d = {};
    try { d = JSON.parse(source.getVariable() || "{}"); } catch (e) { d = {}; }
    var url = COMMENT_BASE + '/comment-viewer.html?book_id=' + (d['last_book_id'] || java.get('book_id') || '') + '&book_tog=true&api_base=' + (d["server"] || getApi());
    var html = this.java.ajax(COMMENT_BASE + '/comment-viewer.html');
    this.java.showBrowser(url, html);
}

// ===== 章评功能 =====
function getChapComments(bookId, itemId, authorUserId) {
    try {
        var java = this.java;
        var source = this.source;
        var d = {};
        try { d = JSON.parse(source.getVariable() || "{}"); } catch (e) { d = {}; }
        var server = d["server"] || getApi();
        var url = COMMENT_BASE + '/comment-viewer.html?book_id=' + encodeURIComponent(String(bookId || '')) + '&item_id=' + encodeURIComponent(String(itemId || '')) + '&chapter_tog=true&api_base=' + encodeURIComponent(String(server || ''));
        var html = java.ajax(COMMENT_BASE + '/comment-viewer.html');
        java.showBrowser(url, html);
    } catch(e) {
        this.java.toast('章评加载失败: ' + e);
    }
}

